export enum PhotoSize {
  SIZE_3X4 = '3x4',
  SIZE_4X6 = '4x6',
  SIZE_5X5 = '5x5' // US Visa / International
}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  GRAY = 'gray', // Added neutral gray
  ORIGINAL = 'original'
}

export enum AppStep {
  CONFIG = 'config', // New start screen
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export enum SkinToneType {
  NATURAL = 'natural', // Tự nhiên
  FAIR = 'fair',       // Trắng sáng
  ROSY = 'rosy',       // Trắng hồng
  TAN = 'tan'          // Ngăm khỏe
}

export interface BeautySettings {
  // Skin
  smoothSkin: number;        // 0-100 (AI Strength)
  blemishIntensity: number;  // 0-100 (AI Strength) - Replaced boolean

  // Skin Tone (Client-side)
  skinToneType: SkinToneType;
  skinToneIntensity: number; // 0-100

  // Lighting & Contrast (Client-side)
  lighting: number;          // -50 to +50
  contrast: number;          // -50 to +50

  // Detailed Makeup (AI)
  lipstickColor: string;     // ID or Label from config
  lipstickIntensity: number; // 0-100

  blushColor: string;        // ID or Label from config
  blushIntensity: number;    // 0-100

  // New Features
  eyebrowIntensity: number;  // 0-100 (Kẻ chân mày)
  eyelashIntensity: number;  // 0-100 (Kẻ lông mi) - NEW
  contourIntensity: number;  // 0-100 (Tạo khối)

  // Hair Features
  hairVolume: number;        // 0-100 (Làm dày/đều tóc)
  hairStyle?: 'original' | 'short' | 'long'; // New Hair Style Option
  hairColor?: string;        // ID or Label from config

  makeupStyle: 'natural' | 'grooming'; // Basic vs Full
}

export interface PhotoSettings {
  size: PhotoSize;
  background: BackgroundType;
  backgroundHex?: string; // New: Supports custom hex colors from config
  clothingPrompt?: string;
  beauty: BeautySettings; 
  printQuantity: number;
  phoneNumber?: string; 
}

export interface SavedPhoto {
  id: string;
  dataUrl: string;
  timestamp: number;
  settings: PhotoSettings;
}

export interface ClothingItem {
  id: string;
  label: string;
  gender: 'male' | 'female';
  icon: string; // Emoji or URL
  prompt: string;
  color: string; // Tailwind class for border/bg
}

export interface LipstickOption {
  id: string;
  label: string;
  hex: string;
}

export interface BlushOption {
  id: string;
  label: string;
  hex: string;
}

export interface HairColorOption {
  id: string;
  label: string; // Used for AI Prompt
  hex: string;   // Used for UI Display
}

export interface BackgroundConfigItem {
  id?: string; // Optional ID for management
  type: BackgroundType;
  label: string;
  hexColor: string; // For UI preview and AI generation
}

// New Interface for Integration
export interface ExternalServiceConfig {
  isIntegrationMode: boolean;
  requiredSize: PhotoSize;
  requiredBackground: BackgroundType;
  requiredQuantity: number;
  returnUrl?: string; // URL to redirect back to App A
  orderId?: string;   // Reference ID from App A
}

export interface AppConfig {
  shopName: string;
  welcomeTitle: string;
  welcomeSubtitle: string;
  contactPhone: string;
  contactZalo: string;
  printFooterText: string;
  themeColorHex: string; // Base HEX color to generate brand palette
  themeMode: 'light' | 'dark' | 'system'; // New: Theme Mode
  language: 'vi' | 'en'; // New: Language
  clothingOptions: ClothingItem[];

  lipstickOptions: LipstickOption[];
  blushOptions: BlushOption[];
  hairColorOptions: HairColorOption[]; 
  backgroundConfig: BackgroundConfigItem[];
  photoRules: Record<string, string[]>; 

  adminPassword?: string; 
  logoUrl?: string; 

  googleScriptUrl?: string;

  // Custom Content Section for StartScreen
  customContentHtml?: string;
  customContentBgColor?: string;
  customContentTextColor?: string;
  customContentSize?: 'sm' | 'md' | 'lg';
  customContentImageUrl?: string; // New: Image for ads
  customContentLinkUrl?: string;  // New: Link for ads
}

import React, { useState, useEffect } from 'react';
import PhotoBooth from './components/PhotoBooth';
import AdminDashboard from './components/AdminDashboard';
import PhotoViewer from './components/PhotoViewer';
import MobileCaptureClient from './components/MobileCaptureClient';
import { AppConfig, PhotoSize, ExternalServiceConfig, BackgroundType } from './types';
import { getConfig, applyTheme, applyThemeMode, updateFavicon, saveConfig } from './services/configService';
import { getAppConfigFromCloud } from './services/databaseService';
import { t } from './services/i18n';

const App: React.FC = () => {
  const [isStarted, setIsStarted] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [config, setConfig] = useState<AppConfig>(getConfig());
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPass, setAdminPass] = useState('');

  const [viewerPhotoId, setViewerPhotoId] = useState<string | null>(null);
  const [mobileSessionId, setMobileSessionId] = useState<string | null>(null);
  const [mobileInitialSize, setMobileInitialSize] = useState<PhotoSize>(PhotoSize.SIZE_4X6);

  const [boothKey, setBoothKey] = useState(0);

  // State for integration with App A
  const [externalConfig, setExternalConfig] = useState<ExternalServiceConfig | null>(null);

  useEffect(() => {
    const loadedConfig = getConfig();
    let finalConfig = { ...loadedConfig };

    const params = new URLSearchParams(window.location.search);

    // 1. Check for Script URL Override
    const querySurl = params.get('surl');
    if (querySurl) {
        finalConfig.googleScriptUrl = decodeURIComponent(querySurl);
        saveConfig(finalConfig);
    }

    setConfig(finalConfig);
    applyTheme(finalConfig.themeColorHex);
    applyThemeMode(finalConfig.themeMode);
    updateFavicon(finalConfig.logoUrl);

    // 2. Sync Config from Cloud
    const syncCloudConfig = async () => {
        if (finalConfig.googleScriptUrl) {
            const cloudConfig = await getAppConfigFromCloud();
            if (cloudConfig) {
                const mergedConfig = { ...cloudConfig, googleScriptUrl: finalConfig.googleScriptUrl };
                setConfig(mergedConfig);
                saveConfig(mergedConfig);
                applyTheme(mergedConfig.themeColorHex);
                applyThemeMode(mergedConfig.themeMode);
                updateFavicon(mergedConfig.logoUrl);
            }
        }
    };
    syncCloudConfig();

    // 3. Check for Photo Viewer Mode
    const photoId = params.get('photoId');
    if (photoId) setViewerPhotoId(photoId);

    // 4. Check for Mobile Session Mode
    const mobileSession = params.get('mobileSession');
    if (mobileSession) {
        setMobileSessionId(mobileSession);
        const sizeParam = params.get('size') as PhotoSize;
        if (sizeParam && Object.values(PhotoSize).includes(sizeParam)) {
            setMobileInitialSize(sizeParam);
        }
    }

    // 5. Check for Integration Mode (App A calling App B)
    // URL Example: ?mode=service&size=3x4&bg=blue&qty=4&returnUrl=https://appa.com/order/123
    const mode = params.get('mode');
    if (mode === 'service') {
        const sizeParam = params.get('size');
        const bgParam = params.get('bg');
        const qtyParam = params.get('qty');
        const returnUrl = params.get('returnUrl');
        const orderId = params.get('orderId');

        // Map params to types
        let reqSize = PhotoSize.SIZE_4X6;
        if (sizeParam === '3x4') reqSize = PhotoSize.SIZE_3X4;
        if (sizeParam === '5x5') reqSize = PhotoSize.SIZE_5X5;

        let reqBg = BackgroundType.WHITE;
        if (bgParam === 'blue') reqBg = BackgroundType.BLUE;
        if (bgParam === 'gray') reqBg = BackgroundType.GRAY;

        const reqQty = qtyParam ? parseInt(qtyParam) : 4;

        setExternalConfig({
            isIntegrationMode: true,
            requiredSize: reqSize,
            requiredBackground: reqBg,
            requiredQuantity: reqQty,
            returnUrl: returnUrl ? decodeURIComponent(returnUrl) : undefined,
            orderId: orderId || undefined
        });

        // Auto start if in integration mode
        setIsStarted(true);
    }

  }, []);

  const handleStart = () => {
    setBoothKey(prev => prev + 1);
    setIsStarted(true);
  };

  const handleHome = () => {
    // If external config exists, maybe redirect back or reset? 
    // For now, reset to start screen but keep config
    if (externalConfig) {
        // If "Home" is clicked in integration mode, we might want to cancel/exit
        if (externalConfig.returnUrl) {
            window.location.href = externalConfig.returnUrl;
            return;
        }
    }
    setIsStarted(false);
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const targetPass = config.adminPassword || 'admin';
    if (adminPass === targetPass) {
      setIsAdminMode(true);
      setShowAdminLogin(false);
      setAdminPass('');
    } else {
      alert('Sai mật khẩu!');
    }
  };

  if (mobileSessionId) {
      return <MobileCaptureClient sessionId={mobileSessionId} config={config} initialSize={mobileInitialSize} />;
  }

  if (viewerPhotoId) {
    return <PhotoViewer photoId={viewerPhotoId} config={config} />;
  }

  if (isAdminMode) {
    return (
      <AdminDashboard 
        currentConfig={config}
        onUpdateConfig={(newConfig) => {
          setConfig(newConfig);
          applyTheme(newConfig.themeColorHex);
          applyThemeMode(newConfig.themeMode);
          updateFavicon(newConfig.logoUrl);
        }}
        onExit={() => setIsAdminMode(false)}
      />
    );
  }

  // Integration Mode: Skip Start Screen Animation if auto-started via useEffect
  if (externalConfig && isStarted) {
     return (
        <div className="h-full w-full font-sans flex flex-col overflow-hidden bg-white dark:bg-gray-900">
           <PhotoBooth 
                key={boothKey} 
                config={config} 
                onHome={handleHome} 
                externalConfig={externalConfig} // Pass the integration config
           />
        </div>
     );
  }

  if (!isStarted) {
    return (
      <div className="min-h-screen w-full bg-gradient-to-br from-slate-900 via-slate-800 to-black flex items-center justify-center p-6 relative overflow-x-hidden font-sans">
        <div className="absolute top-0 left-0 w-96 h-96 bg-brand-600/20 rounded-full blur-[100px] -translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 right-0 w-[500px] h-[500px] bg-brand-600/10 rounded-full blur-[120px] translate-x-1/3 translate-y-1/3"></div>

        <div className="text-center space-y-10 animate-fadeIn z-10 max-w-2xl w-full relative">
          <div className="relative w-32 h-32 md:w-40 md:h-40 mx-auto group">
             {config.logoUrl ? (
                <div className="relative w-full h-full bg-white rounded-3xl shadow-2xl flex items-center justify-center transform rotate-6 group-hover:rotate-0 transition-all duration-500 ease-out border-4 border-slate-50 overflow-hidden">
                   <img src={config.logoUrl} alt="Logo" className="w-full h-full object-contain p-2" />
                </div>
             ) : (
                <>
                  <div className="absolute inset-0 bg-brand-500 rounded-3xl blur-2xl opacity-20 group-hover:opacity-40 transition-opacity duration-500"></div>
                  <div className="relative w-full h-full bg-white rounded-3xl shadow-2xl flex items-center justify-center transform rotate-6 group-hover:rotate-0 transition-all duration-500 ease-out border-4 border-slate-50">
                      <svg className="w-16 h-16 md:w-24 md:h-24 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                  </div>
                </>
             )}
          </div>

          <div className="space-y-4">
            <h1 className="text-4xl md:text-6xl font-black text-white tracking-tight drop-shadow-lg">{config.welcomeTitle} <span className="text-brand-500">Pro</span></h1>
            <p className="text-slate-400 text-base md:text-xl max-w-lg mx-auto leading-relaxed">{config.welcomeSubtitle}</p>
          </div>

          <button onClick={handleStart} className="group relative px-8 py-4 md:px-10 md:py-5 bg-gradient-to-r from-brand-600 to-brand-500 hover:from-brand-500 hover:to-brand-400 text-white rounded-2xl font-bold text-xl md:text-2xl shadow-xl transition-all duration-300 flex items-center gap-4 mx-auto overflow-hidden ring-4 ring-white/10 active:scale-95">
            <span>{t('btn.start', config)}</span>
            <svg className="w-6 h-6 md:w-8 md:h-8 group-hover:translate-x-2 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
          </button>
        </div>

        <button onClick={() => setShowAdminLogin(true)} className="absolute bottom-6 left-6 flex items-center gap-2 px-3 py-2 bg-white/10 hover:bg-white/20 text-slate-400 hover:text-white rounded-full transition-all backdrop-blur-sm border border-white/5 hover:border-white/20 group z-50">
          <span className="text-[10px] font-black uppercase tracking-wider">Admin</span>
        </button>

        {showAdminLogin && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] backdrop-blur-sm animate-fadeIn">
            <div className="bg-white p-6 rounded-2xl w-80 shadow-2xl dark:bg-gray-800 border dark:border-gray-700">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg text-gray-800 dark:text-white">{t('btn.login', config)}</h3>
                <button onClick={() => setShowAdminLogin(false)} className="text-gray-400 hover:text-gray-600"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg></button>
              </div>
              <form onSubmit={handleAdminLogin}>
                <input type="password" autoFocus placeholder="Mật khẩu..." value={adminPass} onChange={(e) => setAdminPass(e.target.value)} className="w-full border border-gray-300 rounded-xl py-2.5 px-4 mb-4 focus:ring-2 focus:ring-brand-500 outline-none dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                <button type="submit" className="w-full py-2.5 bg-brand-600 text-white rounded-xl font-bold shadow-lg transform active:scale-95">{t('btn.login', config)}</button>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="h-full w-full font-sans flex flex-col overflow-hidden bg-white dark:bg-gray-900">
      <PhotoBooth key={boothKey} config={config} onHome={handleHome} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import StartScreen from './StartScreen';
import CameraCapture from './CameraCapture';
import ImageEditor from './ImageEditor';
import PrintPreview from './PrintPreview';
import { AppStep, BackgroundType, PhotoSettings, PhotoSize, SavedPhoto, AppConfig, SkinToneType, ExternalServiceConfig } from '../types';

interface PhotoBoothProps {
  onSaveToGallery?: () => void;
  initialPhoto?: SavedPhoto | null;
  onHome: () => void;
  config: AppConfig;
  externalConfig?: ExternalServiceConfig | null; // New Prop
}

const PhotoBooth: React.FC<PhotoBoothProps> = ({ onSaveToGallery, initialPhoto, onHome, config, externalConfig }) => {

  // Determine Initial Step
  const getInitialStep = () => {
    if (initialPhoto) return AppStep.PRINT;
    if (externalConfig?.isIntegrationMode) return AppStep.CAPTURE; // Skip Config if Integrated
    return AppStep.CONFIG;
  };

  const [step, setStep] = useState<AppStep>(getInitialStep());

  // Data State
  const [capturedImage, setCapturedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');
  const [processedImage, setProcessedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');

  // Determine default or forced settings
  const getInitialSettings = (): PhotoSettings => {
    if (initialPhoto) return initialPhoto.settings;

    // Find default hex for background
    const getBgHex = (type: BackgroundType) => {
        const found = config.backgroundConfig.find(b => b.type === type);
        if (found) return found.hexColor;
        // Fallback defaults
        if (type === BackgroundType.BLUE) return '#2792ff';
        if (type === BackgroundType.GRAY) return '#d1d5db';
        return '#ffffff';
    };

    if (externalConfig) {
        return {
            size: externalConfig.requiredSize,
            background: externalConfig.requiredBackground,
            backgroundHex: getBgHex(externalConfig.requiredBackground),
            clothingPrompt: undefined,
            printQuantity: externalConfig.requiredQuantity,
            phoneNumber: config.contactZalo,
            beauty: {
                smoothSkin: 0,
                blemishIntensity: 0,
                hairVolume: 0,
                hairStyle: 'original',
                makeupStyle: 'natural',
                skinToneType: SkinToneType.NATURAL,
                skinToneIntensity: 0,
                lighting: 0,
                contrast: 0,
                lipstickColor: 'pink',
                lipstickIntensity: 0,
                blushColor: 'pink_soft',
                eyebrowIntensity: 0,
                eyelashIntensity: 0,
                contourIntensity: 0,
                blushIntensity: 0
            }
        };
    }

    // Default standalone settings
    return {
        size: PhotoSize.SIZE_4X6,
        background: BackgroundType.WHITE,
        backgroundHex: '#ffffff',
        clothingPrompt: undefined,
        beauty: {
          smoothSkin: 0,
          blemishIntensity: 0,
          hairVolume: 0,
          hairStyle: 'original',
          makeupStyle: 'natural',
          skinToneType: SkinToneType.NATURAL,
          skinToneIntensity: 0,
          lighting: 0,
          contrast: 0,
          lipstickColor: 'pink',
          lipstickIntensity: 0,
          blushColor: 'pink_soft',
          eyebrowIntensity: 0,
          eyelashIntensity: 0,
          contourIntensity: 0,
          blushIntensity: 0
        },
        printQuantity: 4,
        phoneNumber: config.contactZalo
    };
  };

  const [settings, setSettings] = useState<PhotoSettings>(getInitialSettings());

  const handleStartConfig = (startConfig: { size: PhotoSize; background: BackgroundType; quantity: number }) => {
    let defaultHex = '#ffffff';
    const foundBg = config.backgroundConfig.find(b => b.type === startConfig.background);
    if (foundBg) defaultHex = foundBg.hexColor;
    else {
        if (startConfig.background === BackgroundType.BLUE) defaultHex = '#2792ff';
        if (startConfig.background === BackgroundType.GRAY) defaultHex = '#d1d5db';
    }

    setSettings({
      ...settings,
      size: startConfig.size,
      background: startConfig.background,
      backgroundHex: defaultHex,
      printQuantity: startConfig.quantity
    });
    setStep(AppStep.CAPTURE);
  };

  const handleCapture = (imageSrc: string) => {
    setCapturedImage(imageSrc);
    setStep(AppStep.EDIT);
  };

  const handleProcessedImage = (img: string) => {
    setProcessedImage(img);
  };

  const resetFlow = () => {
    setCapturedImage('');
    setProcessedImage('');
    // If external, go back to capture, don't allow changing size
    if (externalConfig) {
        setStep(AppStep.CAPTURE);
    } else {
        setStep(AppStep.CONFIG);
    }
  };

  const handleRetake = () => {
    setCapturedImage('');
    setStep(AppStep.CAPTURE);
  };

  return (
    <div className="h-full w-full">
      {step === AppStep.CONFIG && !externalConfig && (
        <StartScreen 
          onStart={handleStartConfig} 
          onHome={onHome} 
          config={config} 
        />
      )}

      {step === AppStep.CAPTURE && (
        <CameraCapture 
          onCapture={handleCapture}
          selectedSize={settings.size}
          onSizeChange={(s) => !externalConfig && setSettings({...settings, size: s})} // Lock size if external
        />
      )}

      {step === AppStep.EDIT && (
        <ImageEditor 
          originalImage={capturedImage}
          settings={settings}
          onUpdateSettings={setSettings}
          onProcessedImage={handleProcessedImage}
          onNext={() => setStep(AppStep.PRINT)}
          onRetake={handleRetake}
          config={config}
        />
      )}

      {step === AppStep.PRINT && (
        <PrintPreview 
          processedImage={processedImage}
          size={settings.size}
          settings={settings}
          onBack={() => setStep(AppStep.EDIT)}
          onNew={resetFlow}
          onSaved={onSaveToGallery}
          onHome={onHome}
          config={config}
          externalConfig={externalConfig} // Pass down to handle completion
        />
      )}
    </div>
  );
};

export default PhotoBooth;
